"""P6 — Seller Health Portfolio Overview"""import streamlit as stimport plotly.graph_objects as goimport numpy as npfrom config import C, apply_theme, to_rgba, HEALTH_COLORS, ALERT_COLORS, HEALTH_SAIN, HEALTH_SURVEILLERfrom components.kpi_cards import kpi_row, section_title, page_headerfrom data.loader import load_healthdef render():    page_header("Seller Health — Portfolio Overview",                "2 309 vendeurs · snapshot Avril 2020 · Gradient Boosting · Recall 100%",                "🏥")    df = load_health()    pct_high   = (df["Priorité Alerte"] == "HIGH").mean() * 100    pct_sain   = (df["Catégorie"] == "Sain").mean() * 100    pct_danger = (df["Catégorie"] == "En danger").mean() * 100    hs_mean    = df["Health Score"].mean()    kpi_row([        {"title": "Health Score moyen", "value": f"{hs_mean:.1f}/100",         "subtitle": "Score composite", "color": "blue", "icon": "💊"},        {"title": "Alertes HIGH", "value": f"{pct_high:.1f}%",         "subtitle": f"{int(pct_high/100*len(df)):,} vendeurs", "color": "red", "icon": "🔴"},        {"title": "Vendeurs sains", "value": f"{pct_sain:.1f}%",         "subtitle": "Health Score ≥ 72", "color": "green", "icon": "✅"},        {"title": "En danger", "value": f"{pct_danger:.1f}%",         "subtitle": "Health Score < 55", "color": "orange", "icon": "⚠️"},        {"title": "Recall modèle ML", "value": "100%",         "subtitle": "Détection précoce", "color": "purple", "icon": "🤖"},    ])    section_title("Distribution du Health Score", "📊")    bins = np.arange(0, 105, 5)    hist_vals, bin_edges = np.histogram(df["Health Score"].dropna(), bins=bins)    bin_centers = (bin_edges[:-1] + bin_edges[1:]) / 2    bar_colors = [        C["green"] if c >= HEALTH_SAIN else C["orange"] if c >= HEALTH_SURVEILLER else C["red"]        for c in bin_centers    ]    fig_hist = go.Figure(go.Bar(        x=bin_centers, y=hist_vals,        marker=dict(color=bar_colors, opacity=0.85,                    line=dict(color=C["bg"], width=0.5)),        hovertemplate="Score %{x:.0f}<br><b>%{y}</b> vendeurs<extra></extra>",    ))    fig_hist.add_vline(x=HEALTH_SAIN, line_dash="dash", line_color=C["green"],                       annotation_text=f"Sain ({HEALTH_SAIN})",                       annotation_font_color=C["green"],                       annotation_position="top right")    fig_hist.add_vline(x=HEALTH_SURVEILLER, line_dash="dash", line_color=C["orange"],                       annotation_text=f"Danger ({HEALTH_SURVEILLER})",                       annotation_font_color=C["orange"],                       annotation_position="top left")    fig_hist.add_vline(x=hs_mean, line_color=C["blue"], line_width=2,                       annotation_text=f"Moy. {hs_mean:.1f}",                       annotation_font_color=C["blue"])    apply_theme(fig_hist, "Vert=Sain · Orange=À surveiller · Rouge=En danger")    fig_hist.update_layout(height=320, showlegend=False)    fig_hist.update_xaxes(title_text="Health Score (0–100)")    fig_hist.update_yaxes(title_text="Nombre de vendeurs")    st.plotly_chart(fig_hist, use_container_width=True)    col1, col2, col3 = st.columns([1, 1, 2])    with col1:        section_title("Catégories de santé")        cats = df["Catégorie"].value_counts()        fig_d1 = go.Figure(go.Pie(            labels=cats.index,            values=cats.values,            hole=0.55,            marker=dict(                colors=[HEALTH_COLORS.get(c, C["blue"]) for c in cats.index],                line=dict(color=C["bg"], width=3)            ),            textinfo="label+percent",            textfont=dict(color=C["text"], size=11),            hovertemplate="%{label}<br><b>%{value}</b> vendeurs · %{percent}<extra></extra>",        ))        apply_theme(fig_d1, "")        fig_d1.update_layout(height=260, margin=dict(t=10, b=10), showlegend=False)        st.plotly_chart(fig_d1, use_container_width=True)    with col2:        section_title("Priorité d'alerte")        alerts = df["Priorité Alerte"].value_counts()        fig_d2 = go.Figure(go.Pie(            labels=alerts.index,            values=alerts.values,            hole=0.55,            marker=dict(                colors=[ALERT_COLORS.get(a, C["blue"]) for a in alerts.index],                line=dict(color=C["bg"], width=3)            ),            textinfo="label+percent",            textfont=dict(color=C["text"], size=11),            hovertemplate="%{label}<br><b>%{value}</b> vendeurs · %{percent}<extra></extra>",        ))        apply_theme(fig_d2, "")        fig_d2.update_layout(height=260, margin=dict(t=10, b=10), showlegend=False)        st.plotly_chart(fig_d2, use_container_width=True)    with col3:        section_title("Health Score vs Note Snapshot")        fig_sc = go.Figure()        for prio in ["HIGH", "MEDIUM", "LOW", "OK"]:            grp = df[df["Priorité Alerte"] == prio]            fig_sc.add_trace(go.Scatter(                x=grp["Note Snapshot"].clip(3.5, 5.0),                y=grp["Health Score"],                mode="markers",                name=prio,                marker=dict(size=5, opacity=0.45, color=ALERT_COLORS[prio]),                hovertemplate=(                    f"<b>Prio {prio}</b><br>"                    "Note : %{x:.2f}<br>"                    "HS : %{y:.1f}<extra></extra>"                ),            ))        fig_sc.add_hline(y=HEALTH_SAIN, line_dash="dash",                         line_color=C["green"], opacity=0.4)        fig_sc.add_hline(y=HEALTH_SURVEILLER, line_dash="dash",                         line_color=C["orange"], opacity=0.4)        fig_sc.add_vline(x=4.7, line_dash="dash",                         line_color=C["border"], opacity=0.4)        apply_theme(fig_sc, "Couleur = priorité alerte")        fig_sc.update_layout(            height=260,            legend=dict(orientation="h", x=0.5, xanchor="center",                        y=1.08, font=dict(size=11))        )        st.plotly_chart(fig_sc, use_container_width=True)    section_title("Top vendeurs HIGH priority — plus bas Health Score", "🚨")    cols_show = ["Nom Vendeur", "Pays", "Note Snapshot", "Health Score",                 "Catégorie", "Probabilité Risque", "Momentum Sentiment", "Nb Avis Total"]    df_high = df[df["Priorité Alerte"] == "HIGH"].nsmallest(15, "Health Score")[cols_show]    st.dataframe(        df_high.style        .background_gradient(subset=["Health Score"], cmap="RdYlGn_r", vmin=20, vmax=80)        .background_gradient(subset=["Note Snapshot"], cmap="RdYlGn", vmin=3.5, vmax=5.0)        .format({            "Note Snapshot": "{:.2f}",            "Health Score": "{:.1f}",            "Probabilité Risque": "{:.3f}",            "Momentum Sentiment": "{:.3f}"        }),        use_container_width=True, height=400    )